html:
{# PURCHASE SETTLEMENT ADVICE — single-page A4 #}
{% set d = get_kisan_settlement_print_data(doc.name) %}
{% set sf = d.summary_footer %}

{# Choose typography density from the number of rows. Presentation only. #}
{% set kpsa_rows = (d.pi_lines|length) + (d.bargain_rows|length) + (d.quality_rows|length) + (d.debit_lines|length) %}
{% if kpsa_rows > 28 %}
    {% set kpsa_density = "kpsa-density-compact" %}
{% elif kpsa_rows > 18 %}
    {% set kpsa_density = "kpsa-density-medium" %}
{% else %}
    {% set kpsa_density = "" %}
{% endif %}

<style>
/* ------------------------------------------------------------------
   PAGE MARGINS
   Frappe reads THIS exact rule (selector ".print-format", longhand
   margin-* properties only) and passes the values to wkhtmltopdf as
   the PDF page margins. Keep it as a separate, plain rule.
   Left = 18 mm filing / punching margin.
   ------------------------------------------------------------------ */
.print-format {
    margin-top: 6mm;
    margin-bottom: 6mm;
    margin-left: 18mm;
    margin-right: 7mm;
}

/* Same margins for browser printing (Print button). */
@page {
    size: A4 portrait;
    margin: 6mm 7mm 6mm 18mm;
}

/* The page margins above are applied by the PDF engine, so the element
   itself must carry no margin/padding (otherwise they would be doubled). */
html, body {
    margin: 0;
    padding: 0;
    background: #fff;
    font-family: Arial, Helvetica, sans-serif;
    color: #111;
}
html body .print-format {
    box-sizing: border-box !important;
    width: auto !important;
    min-width: 0 !important;
    max-width: none !important;
    margin: 0 !important;
    padding: 0 !important;
}
html body .print-format .print-format-margin {
    width: auto !important;
    max-width: none !important;
    margin: 0 !important;
    padding: 0 !important;
}

/* ------------------------------------------------------------------
   BASEs
   ------------------------------------------------------------------ */
.kpsa-a4 {
    width: 100% !important;
    max-width: 100% !important;
    zoom: 0.88;
    background: #fff;
    box-sizing: border-box;
}
.kpsa-closing { page-break-inside: avoid; }
.kpsa {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 8pt;
    line-height: 1.2;
    color: #111;
}
.kpsa table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
}
/* Every cell stays on ONE line; anything too long is clipped with "…"
   instead of wrapping onto a second line or crossing the border. */
.kpsa td, .kpsa th {
    border: 1px solid #222;
    padding: 2px 3px;
    vertical-align: middle;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.kpsa .wrap {
    white-space: normal;
    overflow: visible;
    text-overflow: clip;
    word-wrap: break-word;
}
.kpsa .nob, .kpsa td.nob, .kpsa th.nob { border: none !important; }
.kpsa .ctr { text-align: center; }
.kpsa .rgt { text-align: right; }
.kpsa .lft { text-align: left; }
.kpsa .b { font-weight: bold; }
.kpsa .block { margin-top: 3px; }
.kpsa .amt { font-variant-numeric: tabular-nums; }

/* ------------------------------------------------------------------
   HEADERs
   ------------------------------------------------------------------ */
.kpsa table.hdr { border: 1px solid #222; }
.kpsa table.hdr td { border: none; }
.kpsa .hdr .logo-cell {
    text-align: center;
    vertical-align: middle;
    padding: 3px;
}
.kpsa .hdr .logo-cell img {
    max-width: 18mm;
    max-height: 15mm;
    width: auto;
    height: auto;
}
.kpsa .hdr .co-cell {
    text-align: center;
    vertical-align: middle;
    padding: 3px 2px;
}
.kpsa .hdr-co {
    font-size: 14pt;
    font-weight: bold;
    color: #0f172a;
    line-height: 1.15;
}
.kpsa .hdr-addr {
    font-size: 8pt;
    line-height: 1.2;
    margin-top: 2px;
    color: #334155;
}
.kpsa .hdr-gst {
    font-size: 8pt;
    margin-top: 1px;
}
.kpsa .hdr .hdr-title {
    border-top: 1px solid #222;
    background: #b4c6e7;
    font-size: 8pt;
    font-weight: bold;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    text-align: center;
    padding: 2px;
}

/* ------------------------------------------------------------------
   TOP SECTIONs (Party / Invoice / Vendor) — a little more breathing room
   ------------------------------------------------------------------ */
.kpsa table.meta-grid > tbody > tr > td.meta-col {
    vertical-align: top;
    padding: 4px 5px;
    white-space: normal;
}
.kpsa table.kv td, .kpsa table.kv th {
    border: none;
    padding: 1.5px 2px;
    font-size: 7.8pt;
    line-height: 1.2;
    vertical-align: top;
    text-align: left;
}
.kpsa table.kv th { font-weight: bold; }
.kpsa table.kv td.addr {
    font-size: 7.2pt;
    line-height: 1.2;
}

/* ------------------------------------------------------------------
   DATA TABLES
   ------------------------------------------------------------------ */
.kpsa .data-table td, .kpsa .data-table th {
    font-size: 8pt;
    padding: 2px 3px;
}
.kpsa .sec-bar td {
    background: #b4c6e7;
    font-weight: bold;
    text-align: center;
    font-size: 7.5pt;
    padding: 1px;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}
.kpsa .tbl-hdr th {
    background: #dce6f2;
    font-weight: bold;
    text-align: center;
}
.kpsa .sec-total td {
    background: #eef2f8;
    font-weight: bold;
}
.kpsa .rate-uom {
    font-size: 6.8pt;
    color: #444;
}
.kpsa .lot-col { font-size: 7pt !important; }

/* Debit note + tax summary side by side */
.kpsa table.pair > tbody > tr > td { border: none; padding: 0; vertical-align: top; }
.kpsa table.pair td.pair-main { width: 70%; }
.kpsa table.pair td.pair-side { width: 30%; padding-left: 3px; }
.kpsa .tax-side .tax-hdr td {
    background: #b4c6e7;
    font-weight: bold;
    text-align: center;
    font-size: 7.5pt;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}
.kpsa .tax-side td.lbl { font-weight: bold; }

/* Settlement summary */
.kpsa .net-row td {
    background: #dce6f2;
    font-weight: bold;
    font-size: 8.5pt;
    padding: 3px;
}
.kpsa .net-row td.net-payable-amt { font-size: 9.5pt; color: #0f172a; }

/* Footer */
.kpsa-closing { page-break-inside: avoid; }
.kpsa .foot-computer {
    margin-top: 3px;
    padding: 2px;
    font-size: 7.5pt;
    font-weight: bold;
    text-align: center;
    border: 1px solid #222;
    background: #f8fafc;
    color: #0f172a;
}
.kpsa .foot-line {
    padding: 2px;
    font-size: 6.5pt;
    text-align: center;
    border: 1px solid #222;
    border-top: none;
}

/* ------------------------------------------------------------------
   DENSITY (more rows -> smaller type so it stays on ONE A4 page)
   ------------------------------------------------------------------ */
.kpsa-density-medium .hdr-co { font-size: 12.5pt; }
.kpsa-density-medium .hdr-addr,
.kpsa-density-medium .hdr-gst { font-size: 7.5pt; }
.kpsa-density-medium table.kv td,
.kpsa-density-medium table.kv th { font-size: 7.3pt; padding: 1px 2px; }
.kpsa-density-medium table.kv td.addr { font-size: 6.8pt; }
.kpsa-density-medium .data-table td,
.kpsa-density-medium .data-table th { font-size: 7.3pt; padding: 1px 3px; }
.kpsa-density-medium .net-row td { font-size: 7.8pt; padding: 2px; }
.kpsa-density-medium .net-row td.net-payable-amt { font-size: 8.5pt; }

.kpsa-density-compact { line-height: 1.1; }
.kpsa-density-compact .hdr .logo-cell img { max-height: 12mm; }
.kpsa-density-compact .hdr-co { font-size: 11pt; }
.kpsa-density-compact .hdr-addr,
.kpsa-density-compact .hdr-gst { font-size: 6.8pt; }
.kpsa-density-compact table.meta-grid > tbody > tr > td.meta-col { padding: 2px 4px; }
.kpsa-density-compact table.kv td,
.kpsa-density-compact table.kv th { font-size: 6.6pt; padding: 0.5px 2px; }
.kpsa-density-compact table.kv td.addr { font-size: 6.2pt; }
.kpsa-density-compact .data-table td,
.kpsa-density-compact .data-table th { font-size: 6.6pt; padding: 0.5px 2px; }
.kpsa-density-compact .sec-bar td,
.kpsa-density-compact .tax-side .tax-hdr td { font-size: 6.6pt; padding: 0.5px; }
.kpsa-density-compact .lot-col { font-size: 6.2pt !important; }
.kpsa-density-compact .rate-uom { font-size: 5.8pt; }
.kpsa-density-compact .net-row td { font-size: 7pt; padding: 1px 2px; }
.kpsa-density-compact .net-row td.net-payable-amt { font-size: 7.6pt; }
.kpsa-density-compact .foot-computer { font-size: 6.4pt; padding: 1px; }
.kpsa-density-compact .foot-line { font-size: 5.8pt; padding: 1px; }

/* ------------------------------------------------------------------
   SCREEN PREVIEW (looks like an A4 sheet with the same margins)
   ------------------------------------------------------------------ */
@media screen {
    html, body { background: #b8bcc4 !important; }
    .layout-main-section-wrapper, .print-preview-wrapper, .print-format-gutter {
        background: #b8bcc4 !important;
        max-width: none !important;
        width: 100% !important;
    }
    html body .print-format {
        width: 210mm !important;
        max-width: 210mm !important;
        min-height: 297mm !important;
        margin: 12px auto !important;
        padding: 6mm 7mm 6mm 18mm !important;
        background: #fff !important;
        box-shadow: 0 2px 14px rgba(0,0,0,.18) !important;
        transform: none !important;
    }
}

@media print {
    html body .print-format,
    html body .print-format .print-format-margin {
        background: transparent !important;
        margin: 0 !important;
        padding: 0 !important;
        box-shadow: none !important;
    }
    .print-format .page-break, .print-format .print-heading { display: none !important; }
    .kpsa .sec-bar td, .kpsa .tbl-hdr th, .kpsa .tax-side .tax-hdr td,
    .kpsa .net-row td, .kpsa .sec-total td, .kpsa .hdr .hdr-title, .kpsa .foot-computer {
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }
}

/* Keep the scaled content inside the printable A4 width. */
.kpsa-a4, .kpsa {
    max-width: 100% !important;
    box-sizing: border-box !important;
}
.kpsa-a4 table {
    max-width: 100%;
}

</style>

<div class="kpsa-a4">
<div class="kpsa {{ kpsa_density }}">

    {# ============================ HEADER ============================ #}
    <table class="hdr">
        <colgroup><col style="width:24mm"><col><col style="width:24mm"></colgroup>
        <tr>
            <td class="logo-cell">
                <img src="/files/kisan_logo.jpeg" alt="{{ d.company_name | e }}">
            </td>
            <td class="co-cell wrap">
                <div class="hdr-co">{{ d.company_name }}</div>
                {% if d.company_address_print or d.company_address_line %}
                <div class="hdr-addr">{{ (d.company_address_print or d.company_address_line) | safe }}</div>
                {% endif %}
                {% if d.company_gstin %}<div class="hdr-gst"><span class="b">GSTIN:</span> {{ d.company_gstin }}</div>{% endif %}
            </td>
            <td></td>
        </tr>
        <tr><td colspan="3" class="hdr-title">Goods Receipt Note &middot; Purchase Settlement Advice</td></tr>
    </table>

    {# ========================= TOP SECTION ========================== #}
    <table class="meta-grid block">
        <colgroup><col style="width:36%"><col style="width:32%"><col style="width:32%"></colgroup>
        <tr>
            <td class="meta-col">
                <table class="kv">
                    <colgroup><col style="width:30%"><col style="width:70%"></colgroup>
                    <tr><th>Party</th><td class="wrap b">{{ d.party }}</td></tr>
                    <tr><th>Location</th><td class="wrap addr">{{ d.party_location_compact or "—" }}</td></tr>
                    <tr><th>Party GSTIN</th><td>{{ d.party_gstin or "—" }}</td></tr>
                    {% if d.broker %}<tr><th>Broker</th><td>{{ d.broker }}</td></tr>{% endif %}
                </table>
            </td>
            <td class="meta-col">
                <table class="kv">
                    <colgroup><col style="width:42%"><col style="width:58%"></colgroup>
                    <tr><th>Our Invoice No.</th><td>{{ d.our_invoice_no }}</td></tr>
                    <tr><th>Invoice Date</th><td>{{ d.invoice_date }}</td></tr>
					<tr><th>Arrival Date</th><td>{{ d.custom_aarrival_date }}</td></tr>
                    <tr><th>Our Location</th><td class="wrap addr">{{ d.our_location_compact or "—" }}</td></tr>
                    <tr><th>Our GSTIN</th><td>{{ d.our_gstin or "—" }}</td></tr>
                    <tr><th>PO No.</th><td>{{ d.po_no or "—" }}</td></tr>
                </table>
            </td>
            <td class="meta-col">
                <table class="kv">
                    <colgroup><col style="width:42%"><col style="width:58%"></colgroup>
                    <tr><th>Debit Note No.</th><td>{{ d.debit_note_no or "—" }}</td></tr>
                    <tr><th>Debit Note Date</th><td>{{ d.debit_note_date or "—" }}</td></tr>
                    <tr><th>Vendor Doc No.</th><td>{{ d.vendor_doc_no or "—" }}</td></tr>
                    <tr><th>Vendor Doc Date</th><td>{{ d.vendor_doc_date or "—" }}</td></tr>
                    <tr><th>Vendor Bill Amt</th><td class="b amt">{{ d.vendor_bill_amount }}</td></tr>
                    <tr><th>Lorry No.</th><td>{{ d.lorry_no or "—" }}</td></tr>
                </table>
            </td>
        </tr>
    </table>

    {# ===================== PURCHASE INVOICE DETAILS ================== #}
    <table class="block data-table">
        <colgroup>
            <col style="width:4%"><col style="width:14%"><col style="width:9%"><col style="width:10%">
            <col style="width:10%"><col style="width:12%"><col style="width:15%"><col style="width:8%"><col style="width:18%">
        </colgroup>
        <tr class="sec-bar"><td colspan="9">Purchase Invoice Details</td></tr>
        <tr class="tbl-hdr">
            <th>Sr.</th><th class="lft">Item</th><th>HSN</th><th>Vendor Wt.</th><th>Rate</th>
            <th>Basic Value</th><th>GST Amt / Rate</th><th>TDS</th><th class="rgt">Payable Amount</th>
        </tr>
        {% for row in d.pi_lines %}
        <tr>
            <td class="ctr">{{ row.sr }}</td>
            <td class="lft">{{ row.item }}</td>
            <td class="ctr">{{ row.hsn }}</td>
            <td class="rgt">{{ row.vendor_dis_wt }}</td>
            <td class="rgt amt">{{ row.rate }}<span class="rate-uom">{{ row.rate_suffix or "" }}</span></td>
            <td class="rgt amt">{{ row.basic }}</td>
            <td class="rgt amt">{{ row.gst }}</td>
            <td class="rgt amt">{{ row.tds or "—" }}</td>
            <td class="rgt amt">{{ row.payable }}</td>
        </tr>
        {% endfor %}
        <tr class="sec-total"><td colspan="8" class="rgt">Total Payable</td><td class="rgt amt">{{ d.pi_total_payable }}</td></tr>
    </table>

    {# ========================= BARGAIN DETAILS ====================== #}
    <table class="block data-table">
        <colgroup>
            <col style="width:17%"><col style="width:13%"><col style="width:7%"><col style="width:10%">
            <col style="width:11%"><col style="width:10%"><col style="width:7%"><col style="width:8%"><col style="width:17%">
        </colgroup>
        <tr class="sec-bar"><td colspan="9">Bargain Details</td></tr>
        <tr class="tbl-hdr">
            <th>Lot No.</th><th class="lft">Item</th><th>Bags</th><th>Gross Wt.</th><th>Sauda Rate</th>
            <th>Arrival Wt.</th><th>Oil %</th><th>Oil Rate</th><th class="rgt">Amount</th>
        </tr>
        {% for row in d.bargain_rows %}
        <tr>
            <td class="lot-col">{{ row.lot_no }}</td>
            <td class="lft">{{ row.item }}</td>
            <td class="rgt">{{ row.bags }}</td>
            <td class="rgt">{{ row.get("gross_weight") or row.get("bags_wt") or "" }}</td>
            <td class="rgt amt">{{ row.sauda_rate }}</td>
            <td class="rgt">{{ row.arrival_weight or "" }}</td>
            <td class="rgt">{{ row.oil_pct or "—" }}</td>
            <td class="rgt">{{ row.oil_rate or "—" }}</td>
            <td class="rgt amt">{{ row.amount }}</td>
        </tr>
        {% endfor %}
        <tr class="sec-total">
            <td colspan="3" class="rgt b">Total</td>
            <td class="rgt b">{{ d.bargain_gross_total or "" }}</td>
            <td></td>
            <td class="rgt b">{{ d.bargain_arrival_total or "" }}</td>
            <td colspan="2"></td>
            <td class="rgt amt b">{{ d.bargain_total }}</td>
        </tr>
    </table>

    {# ================= QUALITY AND OTHER DEDUCTIONS ================= #}
    <table class="block data-table">
        <colgroup>
            <col style="width:4%"><col style="width:46%"><col style="width:10%">
            <col style="width:10%"><col style="width:10%"><col style="width:20%">
        </colgroup>
        <tr class="sec-bar"><td colspan="6">Quality and Other Deductions</td></tr>
        <tr class="tbl-hdr">
            <th>Sr.</th><th class="lft">Particulars</th><th>Req.</th><th>Act.</th><th>Diff.</th><th class="rgt">Value</th>
        </tr>
        {% if d.quality_rows %}
            {% for row in d.quality_rows %}
            <tr>
                <td class="ctr">{{ row.sr }}</td>
                <td class="lft">{{ row.particulars }}</td>
                <td class="ctr">{{ row.required }}</td>
                <td class="ctr">{{ row.actual }}</td>
                <td class="ctr">{{ row.diff }}</td>
                <td class="rgt amt">{{ row.value }}</td>
            </tr>
            {% endfor %}
        {% else %}
            <tr><td colspan="6" class="ctr">—</td></tr>
        {% endif %}
        <tr class="sec-total"><td colspan="5" class="rgt">Total Deduction</td><td class="rgt amt">{{ d.quality_total }}</td></tr>
    </table>

    {# ============== DEBIT NOTE DETAILS + TAX SUMMARY ================ #}
    <table class="pair block">
        <tr>
            <td class="pair-main"{% if not d.debit_tax_sidebar %} style="width:100%"{% endif %}>
                <table class="data-table">
                    <colgroup>
                        <col style="width:6%"><col style="width:35%"><col style="width:9%">
                        <col style="width:13%"><col style="width:16%"><col style="width:21%">
                    </colgroup>
                    <tr class="sec-bar"><td colspan="6">Debit Note Details</td></tr>
                    <tr class="tbl-hdr">
                        <th>Sr.</th><th class="lft">Particulars</th><th>HSN</th><th>Qty / Nos</th><th>Rate</th><th class="rgt">Amount</th>
                    </tr>
                    {% if d.debit_lines %}
                        {% for row in d.debit_lines %}
                        <tr>
                            <td class="ctr">{% if row.sr %}{{ "%02d"|format(row.sr|int) }}{% endif %}</td>
                            <td class="lft">{{ row.particulars }}</td>
                            <td class="ctr">{{ row.hsn or "—" }}</td>
                            <td class="rgt">{% if not row.is_quality_row %}{{ row.get("dn_qty") or row.get("qty") or "—" }}{% endif %}</td>
                            <td class="rgt amt">{% if not row.is_quality_row %}{{ row.get("dn_rate") or row.get("rate") or "—" }}{% endif %}</td>
                            <td class="rgt amt">{{ row.amount }}</td>
                        </tr>
                        {% endfor %}
                    {% else %}
                        <tr><td colspan="6" class="ctr">—</td></tr>
                    {% endif %}
                </table>
            </td>
            {% if d.debit_tax_sidebar %}
            <td class="pair-side">
                <table class="data-table tax-side">
                    <colgroup><col style="width:56%"><col style="width:44%"></colgroup>
                    <tr class="tax-hdr"><td colspan="2">Tax Summary</td></tr>
                    {% for line in d.debit_tax_sidebar %}
                    <tr>
                        <td class="lbl">{{ line.label }}</td>
                        <td class="rgt amt{% if line.bold %} b{% endif %}">{{ line.amount }}</td>
                    </tr>
                    {% endfor %}
                </table>
            </td>
            {% endif %}
        </tr>
    </table>

    {# ====================== SETTLEMENT SUMMARY ===================== #}
    <div class="kpsa-closing">
        <table class="block data-table">
            <colgroup>
                <col style="width:25%"><col style="width:25%"><col style="width:25%"><col style="width:25%">
            </colgroup>
            <tr class="sec-bar"><td colspan="4">Settlement Summary</td></tr>
            <tr class="tbl-hdr">
                <th class="lft">Document</th><th class="rgt">Basic Net of TDS</th><th class="rgt">GST Amount</th><th class="rgt">Net Payable</th>
            </tr>
            <tr>
                <td class="lft">{{ d.summary_pi.document }}</td>
                <td class="rgt amt">{{ d.summary_pi.basic_net_tds }}</td>
                <td class="rgt amt">{{ d.summary_pi.gst }}</td>
                <td class="rgt amt">{{ d.summary_pi.net_payable }}</td>
            </tr>
            <tr>
                <td class="lft">{{ d.summary_debit.document }}</td>
                <td class="rgt amt">{{ d.summary_debit.basic_net_tds }}</td>
                <td class="rgt amt">{{ d.summary_debit.gst }}</td>
                <td class="rgt amt">{{ d.summary_debit.net_payable }}</td>
            </tr>
            <tr class="net-row">
                <td class="lft">{{ sf.document }}</td>
                <td class="rgt amt">{{ sf.basic_net_tds }}</td>
                <td class="rgt amt">{{ sf.gst }}</td>
                <td class="rgt amt net-payable-amt">{{ sf.net_payable }}</td>
            </tr>
        </table>

        <div class="foot-computer">
            This is a computer-generated document and does not require a signature.
        </div>
        <div class="foot-line">
            This Settlement advice is full and final. In case of any dispute, it must be intimated within 5 days from the date of advice otherwise, the settlement will be treated as final.
        </div>
    </div>

</div>
</div>
